import json
import csv

def answer() -> int:
    price_map = {}
    with open('/app/dataset/product_catalog.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            price = float(row['unit_price'].replace(',', '.'))
            price_map[row['product_id'].strip()] = price
            price_map[row['ean_code'].strip()] = price

    total_revenue = 0
    with open('/app/dataset/warehouse_dispatches.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['timestamp'].strip() == '2023-07-18 03:17:00':
                continue
            pid = row['product_id'].strip()
            total_revenue += int(row['quantity']) * price_map[pid]

    return int(total_revenue)

if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

